<?php if (!empty($modoImpressao)): ?><table><thead><tr><th>Data</th><th>Utilizador</th><th>Ação</th><th>Tabela</th><th>Registo</th><th>IP</th></tr></thead><tbody><?php foreach($logs as $log): ?><tr><td><?=htmlspecialchars($log['criado_em'])?></td><td><?=htmlspecialchars($log['usuario_nome']??'Sistema')?></td><td><?=htmlspecialchars($log['acao'])?></td><td><?=htmlspecialchars($log['tabela_afetada']??'')?></td><td><?=htmlspecialchars($log['registo_id']??'')?></td><td><?=htmlspecialchars($log['ip_origem']??'')?></td></tr><?php endforeach?></tbody></table><?php return; endif; ?>
<div class="relatorio-header"><div><h1 class="relatorio-titulo"><i class="fa-solid fa-clipboard-list"></i> Logs de Auditoria</h1><p class="relatorio-subtitulo">Registos imutáveis das operações efectuadas no sistema.</p></div><a class="btn btn-success" href="<?=URL_BASE?>/logs/exportar?<?=htmlspecialchars(http_build_query($filtros))?>"><i class="fa-solid fa-file-csv"></i> Exportar CSV</a></div>
<div class="relatorio-filtros"><form method="get" action="<?=URL_BASE?>/logs/index" style="display:flex;gap:12px;flex-wrap:wrap"><select name="usuario_id"><option value="">Todos os utilizadores</option><?php foreach($usuarios as $u):?><option value="<?=$u['id']?>" <?=$filtros['usuario_id']==$u['id']?'selected':''?>><?=htmlspecialchars($u['nome'])?></option><?php endforeach?></select><input name="acao" placeholder="Acção" value="<?=htmlspecialchars($filtros['acao'])?>"><input name="tabela_afetada" placeholder="Tabela" value="<?=htmlspecialchars($filtros['tabela_afetada'])?>"><input type="date" name="inicio" value="<?=htmlspecialchars($filtros['inicio'])?>"><input type="date" name="fim" value="<?=htmlspecialchars($filtros['fim'])?>"><button class="btn btn-primary">Filtrar</button></form></div>
<div class="relatorio-tabela"><div class="tabela-scroll"><table><thead><tr><th>Data</th><th>Utilizador</th><th>Acção</th><th>Tabela</th><th>Registo</th><th></th></tr></thead><tbody><?php foreach($logs as $log):?><tr><td><?=htmlspecialchars(date('d/m/Y H:i',strtotime($log['criado_em'])))?></td><td><?=htmlspecialchars($log['usuario_nome']??'Sistema')?></td><td><?=htmlspecialchars($log['acao'])?></td><td><?=htmlspecialchars($log['tabela_afetada']??'')?></td><td><?=htmlspecialchars($log['registo_id']??'')?></td><td><button class="btn btn-outline btn-sm" onclick="verDetalhes(<?=$log['id']?>)">Detalhes</button></td></tr><?php endforeach?></tbody></table></div></div>
<div id="detalhes-log" class="form-card" style="display:none;margin-top:16px"><pre></pre></div><script>function verDetalhes(id){fetch('<?=URL_BASE?>/logs/detalhes/'+id).then(r=>r.json()).then(d=>{const el=document.getElementById('detalhes-log');el.style.display='block';el.querySelector('pre').textContent=JSON.stringify({antigos:d.dados_antigos,novos:d.dados_novos},null,2)})}</script>
